-- Add the reviewed overnight leave-in mode without changing existing product rows.
BEGIN;

ALTER TABLE public.product_bondbuilder_specs
  DROP CONSTRAINT IF EXISTS product_bondbuilder_specs_application_mode_check,
  ADD CONSTRAINT product_bondbuilder_specs_application_mode_check CHECK (
    application_mode IN ('pre_shampoo', 'post_wash_leave_in', 'bedtime_leave_in')
  );

-- Both replacements below are intentionally byte-for-byte copies of the
-- installed V1 bodies, apart from the explicit bedtime enum/projection seam.
-- Refuse an unreviewed predecessor rather than overwriting a later change.
DO $preimage$
DECLARE
  schema_body text;
  admission_body text;
BEGIN
  SELECT prosrc INTO schema_body
  FROM pg_catalog.pg_proc
  WHERE oid = 'public.bondbuilder_internal_admission_schema_v1()'::regprocedure;
  SELECT prosrc INTO admission_body
  FROM pg_catalog.pg_proc
  WHERE oid = 'public.bondbuilder_internal_admit_v1(jsonb,text,uuid,text)'::regprocedure;

  IF pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(schema_body, 'UTF8')), 'hex')
       IS DISTINCT FROM '462d89c8a73052750e014cfabfcc16500156fc2d6c5e35ee8e1eaf01eafc382c'
    OR pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(admission_body, 'UTF8')), 'hex')
       IS DISTINCT FROM '67782561cb8b73056732eb89a5c8237aea403bbe2402bf509cf35ad49317fb95'
  THEN
    RAISE EXCEPTION 'Bondbuilder bedtime application mode predecessor drifted';
  END IF;
END $preimage$;

-- This must stay byte-equivalent to bondbuilderInternalAdmissionJsonSchema().
CREATE OR REPLACE FUNCTION public.bondbuilder_internal_admission_schema_v1()
RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path = '' AS $$
 SELECT convert_from(decode('','base64'),'UTF8')::jsonb
$$;

CREATE OR REPLACE FUNCTION public.bondbuilder_internal_admit_v1(p_request jsonb,p_expected_sha256 text,p_request_id uuid,p_reviewed_by text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE request_sha text; profile jsonb; spec jsonb; product public.products%ROWTYPE; v_brand_id uuid; v_line_id uuid; v_brand_name text; v_line_name text; prior public.catalog_enrichment_applied_items%ROWTYPE; batch text; key text; expected jsonb; readback jsonb; canonical text; ident jsonb;
BEGIN
 IF p_request_id IS NULL OR p_reviewed_by IS DISTINCT FROM 'nick' OR p_expected_sha256 !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'internal Bondbuilder approval binding required'; END IF;
 IF NOT public.bondbuilder_shape_valid_v1(p_request,public.bondbuilder_internal_admission_schema_v1()) THEN RAISE EXCEPTION 'invalid internal Bondbuilder admission request'; END IF;
 request_sha:=encode(sha256(convert_to(public.bondbuilder_json_canonical_v1(p_request),'UTF8')),'hex');
 IF request_sha IS DISTINCT FROM p_expected_sha256 OR p_request#>>'{review,reviewed_by}' IS DISTINCT FROM p_reviewed_by THEN RAISE EXCEPTION 'internal Bondbuilder request hash or reviewer mismatch'; END IF;
 profile:=p_request#>'{category_specs,product_bondbuilder_specs,research_profile}'; spec:=p_request#>'{category_specs,product_bondbuilder_specs}';
 IF NOT public.bondbuilder_profile_valid_v1(profile) OR profile#>>'{identity,product_id}' IS NOT NULL
 OR p_request#>>'{review,profile_sha256}' IS DISTINCT FROM profile#>>'{review,profile_sha256}'
 OR p_request#>>'{review,image_sha256}' IS DISTINCT FROM p_request#>>'{product,canonical_image_sha256}'
 OR p_request#>>'{product,thumbnail_image_url}' IS DISTINCT FROM 'https://pqdkhefxsxkyeqelqegq.supabase.co/storage/v1/object/public/product-images/thumbnails/search-v1/'||(p_request#>>'{product,canonical_image_sha256}')||'.webp'
 OR p_request#>>'{product,image_url}' !~ ('^https://pqdkhefxsxkyeqelqegq[.]supabase[.]co/storage/v1/object/public/product-images/[A-Za-z0-9/_-]+-'||left(p_request#>>'{product,canonical_image_sha256}',12)||'[.]webp$')
 OR (p_request#>>'{product,net_content_value}' IS NULL) IS DISTINCT FROM (p_request#>>'{product,net_content_unit}' IS NULL)
  OR (p_request#>>'{product,price_eur}')::numeric IS DISTINCT FROM round((p_request#>>'{product,price_eur}')::numeric,2)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(jsonb_build_array(p_request#>>'{product,affiliate_link}',p_request#>>'{image,source_page_url}',p_request#>>'{image,source_image_url}')) u(value) WHERE u.value IS NOT NULL AND u.value !~ '^https://[^/?#[:space:]]+([/?#][^[:space:]]*)?$')
 THEN RAISE EXCEPTION 'internal Bondbuilder semantic request mismatch'; END IF;
 IF profile#>>'{identity,gtin}' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_request->'identifiers') x WHERE x.value->>'type'='gtin' AND public.product_identifier_canonical_gtin14('gtin',x.value->>'value')=public.product_identifier_canonical_gtin14('gtin',profile#>>'{identity,gtin}')) THEN RAISE EXCEPTION 'internal Bondbuilder profile GTIN is not bound'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_request->'identifiers') x WHERE x.value->>'type'='retailer_url' AND x.value->>'value' !~ '^https://[^/?#[:space:]]+([/?#][^[:space:]]*)?$') OR EXISTS(SELECT 1 FROM (SELECT x.value->>'type' AS type,COALESCE(public.product_identifier_canonical_gtin14('gtin',x.value->>'value'),x.value->>'value') AS value,count(*) FROM jsonb_array_elements(p_request->'identifiers') x GROUP BY 1,2 HAVING count(*)>1) duplicate_identifier) THEN RAISE EXCEPTION 'invalid or duplicate internal Bondbuilder identifier'; END IF;
 expected:=jsonb_build_object('technology_family',profile#>>'{assessment,technology_family}','claim_trust_level',profile#>>'{assessment,claim_trust_level}','trust_basis',profile#>>'{assessment,trust_basis}','research_profile',profile);
 IF profile#>>'{application,placement,value}'='pre_shampoo' THEN expected:=expected||jsonb_build_object('application_mode','pre_shampoo'); END IF;
 IF profile#>>'{application,placement,value}'='post_shampoo' AND profile#>>'{application,rinse,value,treatment_mode}'='leave_in' THEN expected:=expected||jsonb_build_object('application_mode','post_wash_leave_in'); END IF;
 IF profile#>'{application,state_modifiers,value}' @> '["at_bedtime"]'::jsonb AND profile#>>'{application,timing,value,kind}'='overnight' AND profile#>>'{application,timing,value,purpose}'='contact' AND profile#>>'{application,rinse,value,treatment_mode}'='leave_in' AND COALESCE((profile#>>'{application,rinse,value,standalone_treatment_rinse}')::boolean,false)=false THEN expected:=expected||jsonb_build_object('application_mode','bedtime_leave_in'); END IF;
 IF profile#>>'{application,rinse,value,treatment_mode}' IS NOT NULL THEN expected:=expected||jsonb_build_object('treatment_mode',profile#>>'{application,rinse,value,treatment_mode}'); END IF;
 IF profile#>>'{application,applied_format,value}'='cream' THEN expected:=expected||jsonb_build_object('product_format','cream_treatment'); END IF;
 IF profile#>>'{application,applied_format,value}'='liquid_spray' THEN expected:=expected||jsonb_build_object('product_format','spray_treatment'); END IF;
 IF spec IS DISTINCT FROM expected THEN RAISE EXCEPTION 'internal Bondbuilder projection mismatch'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('catalog-enrichment:product-apply',0));
 batch:='bondbuilder-internal-admission-v1:'||p_request_id::text; key:=p_request_id::text;
 PERFORM pg_advisory_xact_lock(hashtextextended(batch,0));
 FOR canonical IN SELECT public.product_identifier_canonical_gtin14('gtin',x.value->>'value') FROM jsonb_array_elements(p_request->'identifiers') x WHERE x.value->>'type'='gtin' ORDER BY 1 LOOP
   IF canonical IS NULL THEN RAISE EXCEPTION 'invalid internal Bondbuilder GTIN'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('product-identifier:canonical-gtin14:'||canonical,0));
 END LOOP;
 SELECT * INTO prior FROM public.catalog_enrichment_applied_items WHERE batch_id=batch AND product_key=key;
 IF FOUND THEN
   SELECT public.bondbuilder_internal_admission_readback_v1(prior.product_id) INTO readback;
   SELECT fact_value INTO expected FROM public.personal_plan_catalog_fact_evidence WHERE product_id=prior.product_id AND fact_key='bondbuilder_internal_admission_request' AND batch_id=batch;
   IF prior.batch_fingerprint IS DISTINCT FROM request_sha OR prior.content_fingerprint IS DISTINCT FROM profile#>>'{review,profile_sha256}' OR prior.reviewed_by IS DISTINCT FROM 'nick' OR expected IS DISTINCT FROM p_request OR readback IS NULL OR (SELECT count(*) FROM public.personal_plan_catalog_fact_evidence e WHERE e.product_id=prior.product_id AND e.batch_id=batch AND e.fact_key IN ('bondbuilder_internal_admission_request','bondbuilder_internal_admission_readback'))<>2 OR NOT EXISTS(SELECT 1 FROM public.personal_plan_catalog_fact_evidence e WHERE e.product_id=prior.product_id AND e.fact_key='bondbuilder_internal_admission_request' AND e.fact_value=p_request AND e.source_label='Reviewed internal Bondbuilder admission' AND e.source_url=p_request#>>'{image,source_page_url}' AND e.source_text='Exact approved request.' AND e.source_type='internal_verified' AND e.checked_at=(profile#>>'{review,checked_date}')::date AND e.batch_id=batch AND e.batch_fingerprint=request_sha AND e.content_fingerprint=profile#>>'{review,profile_sha256}') OR NOT EXISTS(SELECT 1 FROM public.personal_plan_catalog_fact_evidence e WHERE e.product_id=prior.product_id AND e.fact_key='bondbuilder_internal_admission_readback' AND e.fact_value=readback AND e.source_label='Reviewed internal Bondbuilder readback' AND e.source_url=p_request#>>'{image,source_page_url}' AND e.source_text='Exact staged catalogue bundle.' AND e.source_type='internal_verified' AND e.checked_at=(profile#>>'{review,checked_date}')::date AND e.batch_id=batch AND e.batch_fingerprint=request_sha AND e.content_fingerprint=profile#>>'{review,profile_sha256}') THEN RAISE EXCEPTION 'internal Bondbuilder replay drift'; END IF;
   RETURN jsonb_build_object('outcome','already_applied','product_id',prior.product_id,'request_sha256',request_sha);
 END IF;
 IF EXISTS(SELECT 1 FROM public.products q LEFT JOIN public.brands b ON b.id=q.brand_id WHERE public.product_intake_review_normalize_identity_text(q.name)=public.product_intake_review_normalize_identity_text(concat_ws(' ',p_request#>>'{product,canonical_brand}',NULLIF(p_request#>>'{product,product_line}',''),p_request#>>'{product,clean_name}')) AND public.product_intake_review_normalize_identity_text(COALESCE(b.canonical_name,q.brand))=public.product_intake_review_normalize_identity_text(p_request#>>'{product,canonical_brand}')) THEN RAISE EXCEPTION 'internal Bondbuilder canonical identity already exists'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_request->'identifiers') x WHERE x.value->>'type'='gtin' AND EXISTS(SELECT 1 FROM public.product_identifiers i WHERE i.canonical_gtin14=public.product_identifier_canonical_gtin14('gtin',x.value->>'value'))) THEN RAISE EXCEPTION 'internal Bondbuilder GTIN already owned'; END IF;
 SELECT b.id,b.canonical_name INTO v_brand_id,v_brand_name FROM public.brands b WHERE b.normalized_name=public.product_intake_review_normalize_identity_text(p_request#>>'{product,canonical_brand}') FOR UPDATE;
 IF v_brand_id IS NULL THEN INSERT INTO public.brands(canonical_name,normalized_name) VALUES(p_request#>>'{product,canonical_brand}',public.product_intake_review_normalize_identity_text(p_request#>>'{product,canonical_brand}')) RETURNING id INTO v_brand_id; ELSIF v_brand_name IS DISTINCT FROM p_request#>>'{product,canonical_brand}' THEN RAISE EXCEPTION 'internal Bondbuilder canonical brand spelling mismatch'; END IF;
 IF p_request#>>'{product,product_line}' IS NOT NULL THEN SELECT l.id,l.canonical_name INTO v_line_id,v_line_name FROM public.product_lines l WHERE l.brand_id=v_brand_id AND l.normalized_name=public.product_intake_review_normalize_identity_text(p_request#>>'{product,product_line}') FOR UPDATE; IF v_line_id IS NULL THEN INSERT INTO public.product_lines(brand_id,canonical_name,normalized_name) VALUES(v_brand_id,p_request#>>'{product,product_line}',public.product_intake_review_normalize_identity_text(p_request#>>'{product,product_line}')) RETURNING id INTO v_line_id; ELSIF v_line_name IS DISTINCT FROM p_request#>>'{product,product_line}' THEN RAISE EXCEPTION 'internal Bondbuilder canonical line spelling mismatch'; END IF; END IF;
 INSERT INTO public.products(name,brand,brand_id,product_line_id,category_key,affiliate_link,image_url,thumbnail_image_url,price_eur,currency,purchase_link_status,purchase_link_checked_at,price_checked_at,net_content_value,net_content_unit,origin,is_active,lifecycle_status,is_chaarlie_recommended,suitable_thicknesses)
 VALUES(concat_ws(' ',p_request#>>'{product,canonical_brand}',NULLIF(p_request#>>'{product,product_line}',''),p_request#>>'{product,clean_name}'),p_request#>>'{product,canonical_brand}',v_brand_id,v_line_id,'bondbuilder',p_request#>>'{product,affiliate_link}',p_request#>>'{product,image_url}',p_request#>>'{product,thumbnail_image_url}',(p_request#>>'{product,price_eur}')::numeric,'EUR','available',(p_request#>>'{product,purchase_link_checked_at}')::timestamptz,(p_request#>>'{product,price_checked_at}')::timestamptz,(p_request#>>'{product,net_content_value}')::numeric,p_request#>>'{product,net_content_unit}','curated',false,'active',false,'{}') RETURNING * INTO product;
 IF NOT public.bondbuilder_profile_catalogue_identity_valid_v1(profile,product.id) THEN RAISE EXCEPTION 'internal Bondbuilder catalogue identity mismatch'; END IF;
 PERFORM public.bondbuilder_write_spec_v1(product.id,spec);
 FOR ident IN SELECT value FROM jsonb_array_elements(p_request->'identifiers') LOOP INSERT INTO public.product_identifiers(product_id,identifier_type,identifier_value,source) VALUES(product.id,ident->>'type',ident->>'value',ident->>'source'); END LOOP;
 INSERT INTO public.product_image_assets(product_id,storage_bucket,storage_path,public_url,source_page_url,source_image_url,source_type,quality_confidence,processing_method,asset_sha256,manifest_batch_id,user_approved,notes)
 VALUES(product.id,'product-images',replace(p_request#>>'{product,image_url}','https://pqdkhefxsxkyeqelqegq.supabase.co/storage/v1/object/public/product-images/',''),p_request#>>'{product,image_url}',p_request#>>'{image,source_page_url}',NULLIF(p_request#>>'{image,source_image_url}',''),p_request#>>'{image,source_type}','high',p_request#>>'{image,processing_method}',p_request#>>'{product,canonical_image_sha256}',batch,true,'Reviewed internal Bondbuilder staging asset');
 SELECT public.bondbuilder_internal_admission_readback_v1(product.id) INTO readback;
 INSERT INTO public.catalog_enrichment_applied_items(batch_id,product_key,batch_fingerprint,content_fingerprint,product_id,reviewed_by) VALUES(batch,key,request_sha,profile#>>'{review,profile_sha256}',product.id,p_reviewed_by);
 INSERT INTO public.personal_plan_catalog_fact_evidence(product_id,fact_key,fact_value,source_label,source_url,source_text,source_type,checked_at,batch_id,batch_fingerprint,content_fingerprint) VALUES
 (product.id,'bondbuilder_internal_admission_request',p_request,'Reviewed internal Bondbuilder admission',p_request#>>'{image,source_page_url}','Exact approved request.','internal_verified',(profile#>>'{review,checked_date}')::date,batch,request_sha,profile#>>'{review,profile_sha256}'),
 (product.id,'bondbuilder_internal_admission_readback',readback,'Reviewed internal Bondbuilder readback',p_request#>>'{image,source_page_url}','Exact staged catalogue bundle.','internal_verified',(profile#>>'{review,checked_date}')::date,batch,request_sha,profile#>>'{review,profile_sha256}');
 RETURN jsonb_build_object('outcome','applied','product_id',product.id,'request_sha256',request_sha);
END $$;

REVOKE ALL ON FUNCTION public.bondbuilder_internal_admission_schema_v1() FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
